static uint32_t get_emmenu_focused_childId(uint32_t child_cnt)
{
    lv_obj_t *ui_em_child = NULL;
    uint32_t child_id = 0;
    for (child_id = 0; child_id < child_cnt; child_id++) {
        ui_em_child = lv_obj_get_child(ui_PnlEmMenu, child_id);
        if (lv_obj_has_state(ui_em_child, LV_STATE_FOCUSED)) {
            break;
        }
        if (child_id == child_cnt - 1) {
            child_id = 0;
            break;
        }
    }
    return child_id;
}
